11: /// CRC16-CCITT generator polynomial ($x^{16} + x^{12} + x^5 + 1$).
12: pub const CRC16_POLYNOMIAL: u16 = 0x1021;
13: 
14: /// Primary initial seed used by DJI flight controllers for `.DAT` CRC16 checksums.
15: pub const CRC16_INIT_PRIMARY: u16 = 0x3692;
16: 
17: /// Secondary fallback initial seed used by certain legacy or alternate DJI firmware.
18: pub const CRC16_INIT_FALLBACK: u16 = 0xFFFF;
19: 
20: /// IEEE 802.3 32-bit generator polynomial (reversed / LSB-first).
21: pub const CRC32_POLYNOMIAL: u32 = 0xEDB8_8320;
22: 
23: /// Compile-time precomputed lookup table for CRC16-CCITT (polynomial `0x1021`).
24: const CRC16_TABLE: [u16; 256] = {
25:     let mut table = [0u16; 256];
26:     let mut i = 0;
27:     while i < 256 {
28:         let mut crc = (i as u16) << 8;
29:         let mut j = 0;
30:         while j < 8 {
31:             if (crc & 0x8000) != 0 {
32:                 crc = (crc << 1) ^ CRC16_POLYNOMIAL;
33:             } else {
34:                 crc <<= 1;
35:             }
36:             j += 1;
37:         }
38:         table[i] = crc;
39:         i += 1;
40:     }
41:     table
42: };
43: 
44: /// Compile-time precomputed lookup table for IEEE 802.3 CRC32 (polynomial `0xEDB88320`).
45: const CRC32_TABLE: [u32; 256] = {
46:     let mut table = [0u32; 256];
47:     let mut i = 0;
48:     while i < 256 {
49:         let mut crc = i as u32;
50:         let mut j = 0;
51:         while j < 8 {
52:             if (crc & 1) != 0 {
53:                 crc = (crc >> 1) ^ CRC32_POLYNOMIAL;
54:             } else {
55:                 crc >>= 1;
56:             }
57:             j += 1;
58:         }
59:         table[i] = crc;
60:         i += 1;
61:     }
62:     table
63: };
