207: /// An iterator that scans and extracts valid `.DAT` telemetry frames from a byte stream.
208: ///
209: /// Handles noisy streams, embedded corruptions, and invalid candidate headers by
210: /// advancing byte-by-byte until a verifiable frame is located, then advancing by `frame.length`.
211: #[derive(Debug, Clone)]
212: pub struct DatFrameIterator<'a> {
213:     buffer: &'a [u8],
214:     cursor: usize,
215: }
216: 
217: impl<'a> DatFrameIterator<'a> {
218:     /// Creates a new `DatFrameIterator` over the given byte buffer.
219:     pub fn new(buffer: &'a [u8]) -> Self {
220:         Self { buffer, cursor: 0 }
221:     }
222: 
223:     /// Returns the current read cursor position within the buffer.
224:     pub fn cursor(&self) -> usize {
225:         self.cursor
226:     }
227: 
228:     /// Returns the remaining unconsumed slice of the buffer.
229:     pub fn remaining(&self) -> &'a [u8] {
230:         if self.cursor >= self.buffer.len() {
231:             &[]
232:         } else {
233:             &self.buffer[self.cursor..]
234:         }
235:     }
236: }
237: 
238: impl<'a> Iterator for DatFrameIterator<'a> {
239:     type Item = Result<DatFrame<'a>>;
240: 
241:     fn next(&mut self) -> Option<Self::Item> {
242:         while self.cursor < self.buffer.len() {
243:             // Find next occurrence of 0x55 magic byte
244:             let rel_sync = match self.buffer[self.cursor..]
245:                 .iter()
246:                 .position(|&b| b == DAT_MAGIC)
247:             {
248:                 Some(pos) => pos,
249:                 None => {
250:                     self.cursor = self.buffer.len();
251:                     return None;
252:                 }
253:             };
254: 
255:             let sync_pos = self.cursor + rel_sync;
256:             self.cursor = sync_pos;
257: 
258:             // Must have at least 2 bytes (magic + length) to evaluate candidate
259:             if self.cursor + 1 >= self.buffer.len() {
260:                 self.cursor = self.buffer.len();
261:                 return None;
262:             }
263: 
264:             let cand_len = self.buffer[self.cursor + 1] as usize;
265: 
266:             // Minimum allowable frame length for any checksum type is 11 bytes
267:             if cand_len < 11 {
268:                 self.cursor += 1;
269:                 continue;
270:             }
271: 
272:             // Check if full candidate frame is available in the buffer
273:             if self.cursor + cand_len > self.buffer.len() {
274:                 self.cursor += 1;
275:                 continue;
276:             }
277: 
278:             let cand_slice = &self.buffer[self.cursor..self.cursor + cand_len];
279: 
280:             match DatFrame::parse(cand_slice) {
281:                 Ok(frame) => {
282:                     self.cursor += cand_len;
283:                     return Some(Ok(frame));
284:                 }
285:                 Err(_) => {
286:                     // Checksum or format verification failed, advance 1 byte to seek next sync
287:                     self.cursor += 1;
288:                     continue;
289:                 }
290:             }
291:         }
292: 
293:         None
294:     }
295: }
