//! Integration tests for DJI `.txt` binary flight log header parsing.
//!
//! Validates fixed 100-byte and 101-byte header decoding across format versions v1 through v14,
//! version capability matrix mapping, application ecosystem (Department) classifications,
//! error condition rejection, and boundary robustness.

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::{
    classify_version, Department, DetailsLocation, ScrambleType, TxtHeader, VersionCapabilities,
};

/// Constructs a synthetic `.txt` log header for testing.
fn make_header(
    details_offset: i64,
    header_length: i16,
    version: u8,
    department: u8,
    scrambled_flag: u8,
    padding: Option<u8>,
    reserved_fill: Option<u8>,
) -> Vec<u8> {
    let total_len = if padding.is_some() || header_length == 101 {
        101
    } else {
        100
    };
    let mut buf = vec![0u8; total_len];
    LittleEndian::write_i64(&mut buf[0..8], details_offset);
    LittleEndian::write_i16(&mut buf[8..10], header_length);
    buf[10] = version;
    buf[11] = department;
    buf[12] = scrambled_flag;

    if let Some(fill) = reserved_fill {
        buf[13..100].fill(fill);
    }

    if let Some(pad) = padding {
        buf[100] = pad;
    }

    buf
}

#[test]
