            expected_scramble: ScrambleType::Aes,
            expected_loc: DetailsLocation::HeaderOffset,
        },
        VectorCase {
            version: 13,
            header_len: 101,
            dept_id: 3,
            expected_dept: Department::DjiFly,
            scrambled: 1,
            details_offset: 101,
            padding: Some(0x00),
            expected_width: 2,
            expected_scramble: ScrambleType::Aes,
            expected_loc: DetailsLocation::HeaderOffset,
        },
        VectorCase {
            version: 14,
            header_len: 100,
            dept_id: 3,
            expected_dept: Department::DjiFly,
            scrambled: 1,
            details_offset: 100,
            padding: None,
            expected_width: 2,
            expected_scramble: ScrambleType::Aes,
            expected_loc: DetailsLocation::HeaderOffset,
        },
        VectorCase {
            version: 14,
            header_len: 101,
            dept_id: 7,
            expected_dept: Department::DjiPilot,
            scrambled: 1,
            details_offset: 101,
            padding: Some(0x00),
            expected_width: 2,
            expected_scramble: ScrambleType::Aes,
            expected_loc: DetailsLocation::HeaderOffset,
        },
    ];

    for tc in test_cases {
        let bytes = make_header(
            tc.details_offset,
            tc.header_len,
            tc.version,
            tc.dept_id,
            tc.scrambled,
            tc.padding,
            Some(0x00),
        );

        let parsed = TxtHeader::parse(&bytes)
            .unwrap_or_else(|e| panic!("Failed to parse version {} header: {:?}", tc.version, e));

        assert_eq!(parsed.version, tc.version);
        assert_eq!(parsed.header_length, tc.header_len);
        assert_eq!(parsed.department, tc.expected_dept);
        assert_eq!(parsed.scrambled_flag, tc.scrambled);
        assert_eq!(parsed.details_offset, tc.details_offset);
        assert_eq!(parsed.padding, tc.padding);
        assert_eq!(parsed.is_scrambled(), tc.scrambled != 0);

        let caps = parsed.capabilities().expect("Valid capabilities");
        assert_eq!(caps.version, tc.version);
        assert_eq!(caps.record_len_width, tc.expected_width);
        assert_eq!(caps.scramble_type, tc.expected_scramble);
        assert_eq!(caps.details_location, tc.expected_loc);
    }
}

