}

#[test]
fn test_error_truncated_inputs_boundary_sweep() {
    // 0 to 99 bytes must all return UnexpectedEof
    for len in 0..100 {
        let truncated = vec![0u8; len];
        let err = TxtHeader::parse(&truncated).unwrap_err();
        assert_eq!(
            err,
            FlightReaderError::UnexpectedEof,
            "Expected UnexpectedEof for buffer length {}",
            len
        );
    }

    // 100 bytes buffer with header_length = 101 must return UnexpectedEof
    let mut h101_missing_pad = make_header(100, 101, 13, 3, 1, None, None);
    h101_missing_pad.truncate(100);
    assert_eq!(h101_missing_pad.len(), 100);
    assert_eq!(
        TxtHeader::parse(&h101_missing_pad).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );
}

