#[test]
fn test_version_capabilities_matrix_completeness() {
    // v1..=6
    for v in 1..=6 {
        let caps = classify_version(v).expect("Supported version");
        assert_eq!(caps.version, v);
        assert_eq!(caps.record_len_width, 1);
        assert_eq!(caps.scramble_type, ScrambleType::None);
        assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
    }

    // v7..=11
    for v in 7..=11 {
        let caps = classify_version(v).expect("Supported version");
        assert_eq!(caps.version, v);
        assert_eq!(caps.record_len_width, 2);
        assert_eq!(caps.scramble_type, ScrambleType::Xor);
        assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
    }

    // v12
    let caps_12 = classify_version(12).expect("Supported version");
    assert_eq!(caps_12.version, 12);
    assert_eq!(caps_12.record_len_width, 2);
    assert_eq!(caps_12.scramble_type, ScrambleType::Xor);
    assert_eq!(caps_12.details_location, DetailsLocation::HeaderOffset);

    // v13..=14
    for v in 13..=14 {
        let caps = classify_version(v).expect("Supported version");
        assert_eq!(caps.version, v);
        assert_eq!(caps.record_len_width, 2);
        assert_eq!(caps.scramble_type, ScrambleType::Aes);
        assert_eq!(caps.details_location, DetailsLocation::HeaderOffset);
    }
}

#[test]
fn test_department_mappings_and_conversions() {
    let standard_mappings = [
        (0u8, Department::Unknown, "Unknown"),
        (1, Department::Sdk, "DJI SDK"),
        (2, Department::DjiGo, "DJI GO"),
        (3, Department::DjiFly, "DJI Fly"),
        (4, Department::AgriculturalMachinery, "Agricultural Machinery"),
        (5, Department::Terra, "DJI Terra"),
        (7, Department::DjiPilot, "DJI Pilot"),
        (8, Department::GsPro, "GS Pro"),
    ];

    for (code, expected_dept, display_str) in standard_mappings {
        assert_eq!(Department::from_u8(code), expected_dept);
        assert_eq!(expected_dept.as_u8(), code);
        assert_eq!(expected_dept.to_string(), display_str);

        // Parse header containing this department
        let h = make_header(10000, 100, 1, code, 0, None, None);
        let parsed = TxtHeader::parse(&h).expect("Parse succeeds");
        assert_eq!(parsed.department, expected_dept);
    }

    // Custom non-standard department codes
    for &unmapped in &[6u8, 9, 10, 42, 200, 255] {
        let custom_dept = Department::from_u8(unmapped);
        assert_eq!(custom_dept, Department::Custom(unmapped));
        assert_eq!(custom_dept.as_u8(), unmapped);
        assert_eq!(custom_dept.to_string(), format!("Custom({unmapped})"));
    }
}

