//! Integration tests for ECMA-182 CRC64 key derivation and cyclic XOR de-scrambling.
//!
//! Validates:
//! - Bit-exact 64-bit key generation against all 72 authoritative reference vectors
//!   across 12 standard record types and 6 seed values.
//! - Algebraic diffusion and zero collisions across all 16 degenerate seeds (multiples of 15).
//! - Exhaustive 14,592-pair uniqueness check across all 57 record types and 256 seeds.
//! - Full 256-seed matrix involutive roundtrip invertibility ($A \oplus K \oplus K = A$).
//! - Real-world telemetry payload reconstruction for OSD (55B), Home (50B), Battery (36B), RC (14B).
//! - Boundary payload lengths (0B, 1B, 2B, 8B, 9B, 16B zeroes/ones, 4096B stress).
//! - Typed error handling for sub-minimal payloads and buffer overflows.

use std::collections::HashSet;

use flightreader_core::crypto::{
    calc_crc64, derive_key, descramble_in_place, descramble_record_in_place,
    descramble_record_to_vec, descramble_slice, descramble_to_vec, CRC64_POLY, CRC64_TABLE,
    MAGIC_KEY,
};
use flightreader_core::error::FlightReaderError;

#[test]
fn test_crc64_table_identity_and_generator() {
    assert_eq!(CRC64_TABLE[0], 0x0000000000000000);
    assert_eq!(CRC64_TABLE[1], 0x42F0E1EBA9EA3693);
    assert_eq!(CRC64_TABLE[255], 0x9AFCE626CE85B507);

    // Verify mathematical generator definition (MSB-first shifting)
    for (i, &table_entry) in CRC64_TABLE.iter().enumerate() {
        let mut crc = (i as u64) << 56;
        for _ in 0..8 {
            if (crc & (1u64 << 63)) != 0 {
                crc = (crc << 1) ^ CRC64_POLY;
            } else {
                crc <<= 1;
            }
        }
        assert_eq!(
            table_entry, crc,
            "CRC64 table mismatch at index {}: static=0x{:016X}, dynamic=0x{:016X}",
            i, table_entry, crc
        );
    }
}

