    let cases = [
        DegenCase { seed: 0, expected_product: 0x0000000000000000, expected_crc: 0xA10A2FFD9AAC5176, expected_bytes: [0x76, 0x51, 0xAC, 0x9A, 0xFD, 0x2F, 0x0A, 0xA1] },
