        DegenCase { seed: 60, expected_product: 0x4444444444444040, expected_crc: 0x6CEE551D7EF094DE, expected_bytes: [0xDE, 0x94, 0xF0, 0x7E, 0x1D, 0x55, 0xEE, 0x6C] },
        DegenCase { seed: 75, expected_product: 0x5555555555555050, expected_crc: 0xF50A2C8A1F8DE22B, expected_bytes: [0x2B, 0xE2, 0x8D, 0x1F, 0x8A, 0x2C, 0x0A, 0xF5] },
        DegenCase { seed: 90, expected_product: 0x6666666666666060, expected_crc: 0xA2C978917269414A, expected_bytes: [0x4A, 0x41, 0x69, 0x72, 0x91, 0x78, 0xC9, 0xA2] },
        DegenCase { seed: 105, expected_product: 0x7777777777777070, expected_crc: 0x430AFB8ABEAB23F2, expected_bytes: [0xF2, 0x23, 0xAB, 0xBE, 0x8A, 0xFB, 0x0A, 0x43] },
        DegenCase { seed: 120, expected_product: 0x8888888888888080, expected_crc: 0x5416663F9BA709A2, expected_bytes: [0xA2, 0x09, 0xA7, 0x9B, 0x3F, 0x66, 0x16, 0x54] },
        DegenCase { seed: 135, expected_product: 0x9999999999999090, expected_crc: 0x864DCDA3BFF13283, expected_bytes: [0x83, 0x32, 0xF1, 0xBF, 0xA3, 0xCD, 0x4D, 0x86] },
        DegenCase { seed: 150, expected_product: 0xAAAAAAAAAAAAA0A0, expected_crc: 0x3A3F44E8099194D3, expected_bytes: [0xD3, 0x94, 0x91, 0x09, 0xE8, 0x44, 0x3F, 0x3A] },
        DegenCase { seed: 165, expected_product: 0xBBBBBBBBBBBBB0B0, expected_crc: 0xDBFCC7F3C553F66B, expected_bytes: [0x6B, 0xF6, 0x53, 0xC5, 0xF3, 0xC7, 0xFC, 0xDB] },
        DegenCase { seed: 180, expected_product: 0xCCCCCCCCCCCCC0C0, expected_crc: 0x878EC48E81DC9AB9, expected_bytes: [0xB9, 0x9A, 0xDC, 0x81, 0x8E, 0xC4, 0x8E, 0x87] },
        DegenCase { seed: 195, expected_product: 0xDDDDDDDDDDDDD0D0, expected_crc: 0x1E6ABD19E0A1EC4C, expected_bytes: [0x4C, 0xEC, 0xA1, 0xE0, 0x19, 0xBD, 0x6A, 0x1E] },
        DegenCase { seed: 210, expected_product: 0xEEEEEEEEEEEEE0E0, expected_crc: 0x49A9E9028D454F2D, expected_bytes: [0x2D, 0x4F, 0x45, 0x8D, 0x02, 0xE9, 0xA9, 0x49] },
