#[test]
fn test_exhaustive_operational_keyspace_zero_collisions() {
    // 57 record types x 256 seeds = 14,592 unique operational key combinations
    let mut key_set = HashSet::with_capacity(57 * 256);
    for record_type in 1..=57u8 {
        for seed in 0..=255u8 {
            let key = derive_key(record_type, seed);
            assert!(
                key_set.insert(key),
                "Keystream collision detected for record_type={}, seed={}",
                record_type,
                seed
            );
        }
    }
    assert_eq!(key_set.len(), 57 * 256);
}

#[test]
fn test_full_256_seed_matrix_involutive_roundtrip_all_engines() {
    let original: Vec<u8> = (0..256).map(|i| (i * 17) as u8).collect();

    for record_type in [1u8, 2, 3, 4, 7, 10, 13, 14, 15, 56] {
        for seed in 0..=255u8 {
            let key = derive_key(record_type, seed);

            // 1. descramble_in_place
            let mut buf_inplace = original.clone();
            descramble_in_place(&mut buf_inplace, key);
            assert_ne!(
                buf_inplace, original,
                "Ciphertext must differ from plaintext for seed {}",
                seed
            );
            descramble_in_place(&mut buf_inplace, key);
            assert_eq!(
                buf_inplace, original,
                "In-place roundtrip failed for type {}, seed {}",
                record_type, seed
            );

            // 2. descramble_slice
            let mut scrambled_slice = vec![0u8; original.len()];
            let mut recovered_slice = vec![0u8; original.len()];
            descramble_slice(&original, &mut scrambled_slice, key).unwrap();
            descramble_slice(&scrambled_slice, &mut recovered_slice, key).unwrap();
            assert_eq!(
                recovered_slice, original,
                "Slice roundtrip failed for type {}, seed {}",
                record_type, seed
            );

            // 3. descramble_to_vec
            let scrambled_vec = descramble_to_vec(&original, key);
            let recovered_vec = descramble_to_vec(&scrambled_vec, key);
            assert_eq!(
                recovered_vec, original,
                "Vec roundtrip failed for type {}, seed {}",
                record_type, seed
            );

            // 4. descramble_record_to_vec
            let mut record_packet = vec![seed];
            record_packet.extend_from_slice(&scrambled_vec);
            let record_recovered =
                descramble_record_to_vec(&record_packet, record_type).unwrap();
            assert_eq!(
                record_recovered, original,
                "Record packet recovery failed for type {}, seed {}",
                record_type, seed
            );
        }
    }
}

