#[test]
fn test_boundary_payload_lengths_and_patterns() {
    let key = [0x5D, 0x73, 0x0A, 0x59, 0x50, 0xF5, 0x13, 0x01]; // OSD seed 42

    // 0 bytes
    assert!(descramble_to_vec(&[], key).is_empty());

    // 1 byte: 0x11 ^ 0x5D = 0x4C
    assert_eq!(descramble_to_vec(&[0x11], key), [0x4C]);

    // 2 bytes: [0x11, 0x22] ^ [0x5D, 0x73] = [0x4C, 0x51]
    assert_eq!(descramble_to_vec(&[0x11, 0x22], key), [0x4C, 0x51]);

    // 8 bytes (exact key span)
    let eight_in = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88];
    let eight_out = [0x4C, 0x51, 0x39, 0x1D, 0x05, 0x93, 0x64, 0x89];
    assert_eq!(descramble_to_vec(&eight_in, key), eight_out);

    // 9 bytes (key wrap-around)
    let nine_in = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99];
    let mut nine_out = [0u8; 9];
    nine_out[..8].copy_from_slice(&eight_out);
    nine_out[8] = 0x99 ^ key[0]; // 0xC4
    assert_eq!(descramble_to_vec(&nine_in, key), nine_out);

    // 16 bytes of zeroes
    let zeroes = [0u8; 16];
    let mut expected_zeroes = [0u8; 16];
    expected_zeroes[..8].copy_from_slice(&key);
    expected_zeroes[8..16].copy_from_slice(&key);
    assert_eq!(descramble_to_vec(&zeroes, key), expected_zeroes);

    // 16 bytes of ones
    let ones = [0xFFu8; 16];
    let not_key: [u8; 8] = [
        !key[0], !key[1], !key[2], !key[3], !key[4], !key[5], !key[6], !key[7],
    ];
    let mut expected_ones = [0u8; 16];
    expected_ones[..8].copy_from_slice(&not_key);
    expected_ones[8..16].copy_from_slice(&not_key);
    assert_eq!(descramble_to_vec(&ones, key), expected_ones);

    // 4096-byte large buffer stress test
    let large_in: Vec<u8> = (0..4096).map(|i| (i % 256) as u8).collect();
    let large_scrambled = descramble_to_vec(&large_in, key);
    for (i, &scrambled_byte) in large_scrambled.iter().enumerate() {
        assert_eq!(scrambled_byte, large_in[i] ^ key[i % 8]);
    }
    let large_recovered = descramble_to_vec(&large_scrambled, key);
    assert_eq!(large_recovered, large_in);
}

#[test]
fn test_crypto_error_handling() {
    // PayloadTooShort for empty payload or 1-byte payload (only seed byte)
    let mut empty_buf: [u8; 0] = [];
    assert_eq!(
        descramble_record_in_place(&mut empty_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 0
        })
    );
    assert_eq!(
        descramble_record_to_vec(&empty_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 0
        })
    );

    let mut one_byte_buf = [42u8];
    assert_eq!(
        descramble_record_in_place(&mut one_byte_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1
        })
    );
    assert_eq!(
        descramble_record_to_vec(&one_byte_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1
        })
    );

    // BufferOverflow in descramble_slice
    let key = [1, 2, 3, 4, 5, 6, 7, 8];
    let src = [0u8; 100];
    let mut small_dst = [0u8; 99];
    assert_eq!(
        descramble_slice(&src, &mut small_dst, key),
        Err(FlightReaderError::BufferOverflow {
            required: 100,
            capacity: 99
        })
    );
}

#[test]
fn test_calc_crc64_standalone_deterministic() {
    let data = b"DJI Flight Log Telemetry Record Keystream Test";
    let crc1 = calc_crc64(data, 0);
    let crc2 = calc_crc64(data, 0);
    assert_eq!(crc1, crc2);
    assert_ne!(crc1, 0);

    // Empty slice returns initial crc
    assert_eq!(calc_crc64(&[], 0x1234567890ABCDEF), 0x1234567890ABCDEF);
}

//! Integration tests for DJI on-board blackbox (`.DAT`) binary frame parsing and stream synchronization.
//!
//! Validates:
//! - 0x55 magic byte synchronization, 9-byte header extraction, and zero-allocation payload slicing.
//! - Dual-checksum validation: CRC16-CCITT (polynomial 0x1021 with seeds 0x3692 and 0xFFFF)
//!   and standard IEEE 802.3 CRC32.
//! - Corrupted candidate frame rejection: bad magic, length < 11, checksum corruption, and truncation.
//! - 77-byte composite noise stream resynchronization recovering all 3 valid frames without panics or false positives.
//! - Resilient scanning across embedded 0x55 bytes in payloads, back-to-back streams, and noise bursts.

use flightreader_core::dat::{
    calc_crc16_ccitt, calc_crc32, verify_crc16, verify_crc16_with_seed, verify_crc32,
    DatChecksumType, DatFrame, DatFrameIterator, CRC16_INIT_FALLBACK, CRC16_INIT_PRIMARY,
    DAT_MAGIC, HEADER_LEN,
};
use flightreader_core::error::FlightReaderError;

