#[test]
fn test_parse_with_explicit_checksum_type() {
    let crc16_bytes = [
        0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
    ];
    let parsed16 = DatFrame::parse_with_checksum(&crc16_bytes, DatChecksumType::Crc16)
        .expect("Explicit CRC16 parse");
    assert_eq!(parsed16.checksum_type, DatChecksumType::Crc16);

    // Requiring CRC32 on an 11-byte frame fails because minimum length is 13
    let err = DatFrame::parse_with_checksum(&crc16_bytes, DatChecksumType::Crc32).unwrap_err();
    assert_eq!(
        err,
        FlightReaderError::InvalidFrameLength {
            length: 11,
            minimum: 13
        }
    );

    let crc32_bytes = [
        0x55, 0x1D, 0x2C, 0x12, 0x00, 0x16, 0x62, 0xBC, 0x00, 0x10, 0x20, 0x30, 0x40, 0x50,
        0x60, 0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x00, 0x2D, 0xE4, 0x7F,
        0xAA,
    ];
    let parsed32 = DatFrame::parse_with_checksum(&crc32_bytes, DatChecksumType::Crc32)
        .expect("Explicit CRC32 parse");
    assert_eq!(parsed32.checksum_type, DatChecksumType::Crc32);
}

#[test]
fn test_corrupted_frame_candidate_rejections() {
    // 1. Bad magic byte != 0x55
    for &bad_magic in &[0x00u8, 0x54, 0x56, 0xAA, 0xFF] {
        let frame = [
            bad_magic, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
        ];
        assert_eq!(
            DatFrame::parse(&frame),
            Err(FlightReaderError::SyncNotFound),
            "Failed for bad magic 0x{:02X}",
            bad_magic
        );
    }

    // 2. Buffer too short for magic or header length
    assert_eq!(DatFrame::parse(&[]), Err(FlightReaderError::UnexpectedEof));
    assert_eq!(
        DatFrame::parse(&[0x55]),
        Err(FlightReaderError::UnexpectedEof)
    );

    // 3. Length field under minimum allowable size (< 11)
    for &bad_len in &[0u8, 1, 5, 8, 9, 10] {
        let frame = [0x55, bad_len, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51];
        assert_eq!(
            DatFrame::parse(&frame),
            Err(FlightReaderError::InvalidFrameLength {
                length: bad_len,
                minimum: 11
            }),
            "Failed for bad length {}",
            bad_len
        );
    }

    // 4. Truncated payload: buffer length < declared length
    let truncated_frame = [
        0x55, 0x1B, 0x2A, 0x01, 0x00, 0x4E, 0x61, 0xBC, 0x00, 0x10, 0x20,
    ]; // Declares 27 bytes (0x1B), but only 11 bytes present
    assert_eq!(
        DatFrame::parse(&truncated_frame),
        Err(FlightReaderError::TruncatedRecord {
            expected: 27,
            available: 11
        })
    );

    // 5. Checksum mismatch in CRC16 frame (payload bit flip)
    let mut bit_flip_frame = [
        0x55, 0x1B, 0x2A, 0x01, 0x00, 0x4E, 0x61, 0xBC, 0x00, 0x10, 0x20, 0x30, 0x40, 0x50,
        0x60, 0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x00, 0x42, 0xDA,
    ];
    bit_flip_frame[9] ^= 0x01; // Corrupt payload byte
    assert!(matches!(
        DatFrame::parse(&bit_flip_frame),
        Err(FlightReaderError::ChecksumMismatch { .. })
    ));

    // 6. Checksum mismatch in CRC16 frame (corrupted trailer bytes)
    let mut bad_trailer = [
        0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
    ];
    bad_trailer[9] = 0x00;
    bad_trailer[10] = 0x00;
    assert!(matches!(
        DatFrame::parse(&bad_trailer),
        Err(FlightReaderError::ChecksumMismatch { .. })
    ));

    // 7. Checksum mismatch in CRC32 frame
    let mut bad_crc32 = [
        0x55, 0x1D, 0x2C, 0x12, 0x00, 0x16, 0x62, 0xBC, 0x00, 0x10, 0x20, 0x30, 0x40, 0x50,
        0x60, 0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x00, 0x00, 0x00, 0x00,
        0x00,
    ];
    bad_crc32[25] = 0xFF;
    assert!(matches!(
        DatFrame::parse(&bad_crc32),
        Err(FlightReaderError::ChecksumMismatch { .. })
    ));
}

#[test]
fn test_crc16_fallback_seed_support() {
    let mut frame = [0u8; 11];
    frame[0] = 0x55;
    frame[1] = 11;
    frame[2] = 0x01; // sequence
    frame[3] = 0x05; // payload_id LE
    frame[4] = 0x00;
    frame[5] = 0x10; // timestamp LE
    frame[6] = 0x20;
    frame[7] = 0x30;
    frame[8] = 0x40;

    // Calculate with fallback seed 0xFFFF
    let crc = calc_crc16_ccitt(&frame[..9], CRC16_INIT_FALLBACK);
    frame[9..11].copy_from_slice(&crc.to_le_bytes());

    // verify_crc16 should succeed using the fallback seed
    assert!(verify_crc16(&frame).is_ok());

    // DatFrame::parse should also succeed
    let parsed = DatFrame::parse(&frame).expect("Parsed with fallback seed");
    assert_eq!(parsed.payload_id, 5);
    assert_eq!(parsed.checksum_type, DatChecksumType::Crc16);

    // Direct seed verification
    assert!(verify_crc16_with_seed(&frame, CRC16_INIT_FALLBACK).is_ok());
    assert!(verify_crc16_with_seed(&frame, CRC16_INIT_PRIMARY).is_err());
}

