#[test]
fn test_resynchronization_with_embedded_0x55_in_payload() {
    // Construct a frame where the payload itself contains repeated 0x55 bytes
    let mut frame_bytes = vec![
        0x55, 17, 10, 0x01, 0x00, 0x50, 0x00, 0x00, 0x00, // Header (9B)
        0x55, 0x55, 0x55, 0x55, 0x55, 0x55, // Payload: 6 bytes of 0x55 (offset 9..15)
        0x00, 0x00, // Checksum placeholder
    ];
    let crc = calc_crc16_ccitt(&frame_bytes[..15], CRC16_INIT_PRIMARY);
    frame_bytes[15..17].copy_from_slice(&crc.to_le_bytes());

    // Wrap frame in arbitrary garbage noise before and after
    let mut noisy_stream = vec![0x12, 0x34, 0x55, 0x02]; // False sync at index 2
    noisy_stream.extend_from_slice(&frame_bytes);
    noisy_stream.extend_from_slice(&[0x99, 0x88, 0x55, 0x55]); // Trailing garbage

    let mut iter = DatFrameIterator::new(&noisy_stream);
    let recovered = iter.next().expect("Should find frame").expect("Valid frame");

    assert_eq!(recovered.length, 17);
    assert_eq!(recovered.sequence, 10);
    assert_eq!(recovered.payload_id, 1);
    assert_eq!(recovered.payload, &[0x55; 6]);
    assert_eq!(recovered.checksum_type, DatChecksumType::Crc16);

    // No further valid frames
    assert!(iter.next().is_none());
}

