#[test]
fn test_iterator_cursor_and_remaining_inspection() {
    let frame1 = [
        0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
    ];
    let trailing = [0xDE, 0xAD, 0xBE, 0xEF];

    let mut stream = Vec::new();
    stream.extend_from_slice(&frame1);
    stream.extend_from_slice(&trailing);

    let mut iter = DatFrameIterator::new(&stream);
    assert_eq!(iter.cursor(), 0);
    assert_eq!(iter.remaining(), &stream[..]);

    let frame = iter.next().expect("Frame exists").expect("Ok frame");
    assert_eq!(frame.length, 11);
    assert_eq!(iter.cursor(), 11);
    assert_eq!(iter.remaining(), &trailing[..]);

    assert!(iter.next().is_none());
    assert_eq!(iter.cursor(), stream.len());
    assert!(iter.remaining().is_empty());
}

