//! Property-based testing suite for OpenFlightReader core engine.
//!
//! Utilizes `proptest` to mathematically verify:
//! 1. Involutive symmetry ($A \oplus K \oplus K = A$) across arbitrary byte payloads and seeds.
//! 2. Keystream 8-byte periodicity across arbitrary buffer lengths.
//! 3. Panic-free guarantees for header parsing (`TxtHeader::parse`) and blackbox streaming
//!    (`DatFrame::parse`, `DatFrameIterator`) across arbitrary random fuzz vectors.
//! 4. Mathematical determinism for checksum generators and enum roundtrips.

use flightreader_core::crypto::{
    calc_crc64, derive_key, descramble_in_place, descramble_record_in_place,
    descramble_record_to_vec, descramble_slice, descramble_to_vec,
};
use flightreader_core::dat::{
    calc_crc16_ccitt, calc_crc32, DatFrame, DatFrameIterator, CRC16_INIT_PRIMARY,
};
use flightreader_core::txt::{classify_version, Department, TxtHeader};
use proptest::prelude::*;

proptest! {
    #![proptest_config(ProptestConfig::with_cases(500))]

    /// Property 1: Involutive roundtrip symmetry of cyclic XOR de-scrambling.
    /// Double application of the 8-byte key restores original plaintext bit-for-bit.
    #[test]
    fn prop_xor_involutive_roundtrip(
        payload in proptest::collection::vec(any::<u8>(), 0..2048),
        seed in any::<u8>(),
        record_type in 1u8..=57u8,
    ) {
        let key = derive_key(record_type, seed);

        // In-place double roundtrip
        let mut in_place_buf = payload.clone();
        descramble_in_place(&mut in_place_buf, key);
        descramble_in_place(&mut in_place_buf, key);
        prop_assert_eq!(&in_place_buf, &payload);

        // Vector double roundtrip
        let scrambled_vec = descramble_to_vec(&payload, key);
        let recovered_vec = descramble_to_vec(&scrambled_vec, key);
        prop_assert_eq!(&recovered_vec, &payload);

        // Slice double roundtrip
        let mut s_buf = vec![0u8; payload.len()];
        let mut r_buf = vec![0u8; payload.len()];
        descramble_slice(&payload, &mut s_buf, key).unwrap();
        descramble_slice(&s_buf, &mut r_buf, key).unwrap();
        prop_assert_eq!(&r_buf, &payload);
    }

    /// Property 2: Keystream 8-byte periodicity across arbitrary stream lengths.
    /// Plaintext of all zeroes directly radiates the repeating 8-byte key.
    #[test]
    fn prop_keystream_8byte_periodicity(
        len in 0..2048usize,
        seed in any::<u8>(),
        record_type in 1u8..=57u8,
    ) {
        let key = derive_key(record_type, seed);
        let zeroes = vec![0u8; len];
        let stream = descramble_to_vec(&zeroes, key);

        prop_assert_eq!(stream.len(), len);
        for (i, &b) in stream.iter().enumerate() {
            prop_assert_eq!(b, key[i % 8], "Byte at offset {} did not match key periodicity", i);
        }
    }

    /// Property 3: Full record payload envelope roundtrip.
    /// When payload >= 1 byte, wrapping with seed byte [seed, payload...] and
    /// applying `descramble_record_to_vec` / in-place recovers original payload.
    #[test]
    fn prop_record_payload_envelope_roundtrip(
        payload in proptest::collection::vec(any::<u8>(), 1..1024),
        seed in any::<u8>(),
        record_type in 1u8..=57u8,
    ) {
        let key = derive_key(record_type, seed);
        let cipher = descramble_to_vec(&payload, key);

        let mut record_packet = Vec::with_capacity(1 + cipher.len());
        record_packet.push(seed);
        record_packet.extend_from_slice(&cipher);

        // Method 1: descramble_record_to_vec
        let recovered = descramble_record_to_vec(&record_packet, record_type).unwrap();
        prop_assert_eq!(&recovered, &payload);

        // Method 2: descramble_record_in_place
        let mut in_place_packet = record_packet.clone();
        let in_place_plain = descramble_record_in_place(&mut in_place_packet, record_type).unwrap();
        prop_assert_eq!(in_place_plain, payload.as_slice());
    }

    /// Property 4: Panic-free guarantee for `TxtHeader::parse` on arbitrary random byte slices.
    #[test]
    fn prop_txt_header_parse_never_panics(
        data in proptest::collection::vec(any::<u8>(), 0..512),
    ) {
        let _ = TxtHeader::parse(&data);
    }

    /// Property 5: Panic-free guarantee for `DatFrame::parse` on arbitrary random byte slices.
    #[test]
    fn prop_dat_frame_parse_never_panics(
        data in proptest::collection::vec(any::<u8>(), 0..512),
    ) {
        let _ = DatFrame::parse(&data);
    }

    /// Property 6: Panic-free guarantee and termination for `DatFrameIterator` on arbitrary random slices.
    #[test]
    fn prop_dat_frame_iterator_never_panics_or_hangs(
        data in proptest::collection::vec(any::<u8>(), 0..2048),
    ) {
        let mut iter = DatFrameIterator::new(&data);
        let mut count = 0;
        while let Some(frame_res) = iter.next() {
            if let Ok(frame) = frame_res {
                prop_assert_eq!(frame.magic, 0x55);
                prop_assert!(frame.length >= 11);
            }
            count += 1;
            // Bound iteration count to prevent pathological unbounded execution
            if count > 2048 {
                panic!("DatFrameIterator executed more iterations than stream length");
            }
        }
        prop_assert_eq!(iter.cursor(), data.len());
    }

    /// Property 7: Checksum generator functions never panic on arbitrary byte inputs.
    #[test]
    fn prop_checksum_functions_never_panic(
        data in proptest::collection::vec(any::<u8>(), 0..1024),
        seed16 in any::<u16>(),
        crc64_init in any::<u64>(),
    ) {
        let _ = calc_crc64(&data, crc64_init);
        let _ = calc_crc16_ccitt(&data, seed16);
        let _ = calc_crc16_ccitt(&data, CRC16_INIT_PRIMARY);
        let _ = calc_crc32(&data);
    }

    /// Property 8: `Department` conversions are roundtrip safe and bijective across all u8 values.
    #[test]
    fn prop_department_roundtrip_all_u8(val in any::<u8>()) {
        let dept = Department::from_u8(val);
        let back = dept.as_u8();
        prop_assert_eq!(back, val);

        let from_trait = Department::from(val);
        prop_assert_eq!(dept, from_trait);

        let into_trait: u8 = dept.into();
        prop_assert_eq!(into_trait, val);

        // Display trait must never panic
        let _ = dept.to_string();
    }

    /// Property 9: `classify_version` is total and panic-free across all u8 values.
    #[test]
    fn prop_classify_version_total(val in any::<u8>()) {
        match classify_version(val) {
            Ok(caps) => {
                prop_assert!(val >= 1 && val <= 14);
                prop_assert_eq!(caps.version, val);
                let _ = caps.to_string();
            }
            Err(e) => {
                prop_assert!(val == 0 || val > 14);
                let _ = e.to_string();
            }
        }
    }
}

